module accu(
    input clk, input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);
    // TODO: implement your 4-input accumulator design here.
    // For testbench verifying, do not modify input and output pin.
    // You can add your own reg and wire.
    // You can use operator "+" for accumulation.
    // Your design should include at least one sequential block.
    // Remove this line after you add your implementation
    //assign 1'b0;
    parameter WAIT_CNT = 2'd0;
    parameter ACCUMULATE_CNT = 2'd1;
    parameter OUTPUT_CNT = 2'd2;
    reg [1:0] cnt;
    reg [1:0] state;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 2'd0;
            state <= WAIT_CNT;
            data_out <= 10'd0;
            valid_out <= 1'b0;
        end
        else begin
            case (state)
                WAIT_CNT: begin
                    if (valid_in == 1'b1) begin
                        cnt <= 2'd0;
                        state <= ACCUMULATE_CNT;
                        data_out <= data_in;
                        valid_out <= 1'b0;
                    end
                    else begin
                        state <= WAIT_CNT;
                        valid_out <= 1'b0;
                    end
                end
                ACCUMULATE_CNT: begin
                    if (cnt == 2'd3) begin
                        state <= OUTPUT_CNT;
                        valid_out <= 1'b1;
                    end
                    else begin
                        cnt <= cnt + 1;
                        data_out <= data_out + data_in;
                        state <= ACCUMULATE_CNT;
                        valid_out <= 1'b0;
                    end
                end
                OUTPUT_CNT: begin
                    if (valid_in == 1'b1) begin
                        cnt <= 2'd0;
                        state <= ACCUMULATE_CNT;
                        data_out <= data_in;
                        valid_out <= 1'b0;
                    end
                    else begin
                        state <= WAIT_CNT;
                        valid_out <= 1'b0;
                    end
                end
            endcase
        end
    end
endmodule
